INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_COUNTER_REFORMATION','Counter-Reformation & Baroque Catholicism',1517,1800)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_IGNATIUS_EXERCISES','primary text','Ignatius of Loyola, Spiritual Exercises (1548)','Christian'),
 ('SRC_TERESA_CASTLE','primary text','Teresa of Ávila, The Interior Castle (1577)','Christian'),
 ('SRC_JOHNCROSS_DARKNIGHT','primary text','John of the Cross, The Dark Night of the Soul (c. 1585)','Christian'),
 ('SRC_DESALES_DEVOUT','primary text','Francis de Sales, Introduction to the Devout Life (1609)','Christian')
INSERT INTO _e VALUES
 ('ENT_EMC_JESUITS','Society of Jesus (Jesuits)','Collective','Devotional collective','Christian','Mission','A','Religious order founded 1540 by Ignatius of Loyola; spearhead of Counter-Reformation education and overseas mission.'),
 ('ENT_EMC_DISCALCED_CARMELITES','Discalced Carmelites','Collective','Devotional collective','Christian','Prayer','A','Reformed contemplative Carmelite branch founded by Teresa of Ávila and John of the Cross (1560s–70s).'),
 ('ENT_EMC_NORTH_AMERICAN_MARTYRS','North American Martyrs','Collective','Devotional collective','Christian','Martyrdom','A','Eight Jesuit missionaries martyred in New France/Iroquoia 1642–1649; canonized 1930.'),
 ('ENT_EMC_IGNATIUS_LOYOLA','Ignatius of Loyola','Saint','Counter-Reformation saint','Christian','Mission','A','Basque founder of the Society of Jesus (1540); author of the Spiritual Exercises; patron of retreats and spiritual directors.'),
 ('ENT_EMC_FRANCIS_XAVIER','Francis Xavier','Saint','Counter-Reformation saint','Christian','Mission','A','Jesuit co-founder; pioneering missionary to India, the Malay archipelago and Japan; patron of the missions.'),
 ('ENT_EMC_TERESA_AVILA','Teresa of Ávila','Saint','Mystic/saint','Christian','Prayer','A','Spanish Carmelite mystic and reformer; Doctor of the Church; author of The Interior Castle and her Life.'),
 ('ENT_EMC_JOHN_CROSS','John of the Cross','Saint','Mystic/saint','Christian','Prayer','A','Spanish Carmelite mystic, poet and reformer with Teresa of Ávila; Doctor of the Church; author of The Dark Night of the Soul.'),
 ('ENT_EMC_PHILIP_NERI','Philip Neri','Saint','Counter-Reformation saint','Christian','Prayer','A','"Apostle of Rome"; founder of the Congregation of the Oratory; figure of Catholic renewal and joyful piety.'),
 ('ENT_EMC_CHARLES_BORROMEO','Charles Borromeo','Saint','Counter-Reformation saint','Christian','Mission','A','Cardinal-archbishop of Milan; leading implementer of the Council of Trent''s reforms and seminary system.'),
 ('ENT_EMC_PETER_CANISIUS','Peter Canisius','Saint','Counter-Reformation saint','Christian','Knowledge','A','Dutch Jesuit, Doctor of the Church; catechist who led the Catholic recovery in German-speaking lands.'),
 ('ENT_EMC_ROBERT_BELLARMINE','Robert Bellarmine','Saint','Counter-Reformation saint','Christian','Knowledge','A','Italian Jesuit cardinal, theologian and controversialist; Doctor of the Church; patron of catechists and canonists.'),
 ('ENT_EMC_ALOYSIUS_GONZAGA','Aloysius Gonzaga','Saint','Counter-Reformation saint','Christian','Healing','A','Italian Jesuit novice who died nursing plague victims in Rome (1591); patron of youth and of those with epidemics.'),
 ('ENT_EMC_ROSE_LIMA','Rose of Lima','Saint','Mystic/saint','Christian','Prayer','A','Peruvian Dominican tertiary mystic; first canonized saint of the Americas; patroness of Latin America.'),
 ('ENT_EMC_MARTIN_PORRES','Martín de Porres','Saint','Mendicant/founder','Christian','Healing','A','Afro-Peruvian Dominican lay brother of Lima; healer and almsgiver; patron of social justice and of mixed-race peoples.'),
 ('ENT_EMC_TURIBIUS_MOGROVEJO','Turibius of Mogrovejo','Saint','Counter-Reformation saint','Christian','Mission','A','Archbishop of Lima; reforming Tridentine pastor of colonial Peru; patron of the Latin American episcopate.'),
 ('ENT_EMC_VINCENT_DE_PAUL','Vincent de Paul','Saint','Mendicant/founder','Christian','Poverty','A','French founder of the Congregation of the Mission (Vincentians) and co-founder of the Daughters of Charity; patron of charitable works.'),
 ('ENT_EMC_LOUISE_MARILLAC','Louise de Marillac','Saint','Mendicant/founder','Christian','Poverty','A','French co-founder with Vincent de Paul of the Daughters of Charity; patroness of social workers.'),
 ('ENT_EMC_FRANCIS_DE_SALES','Francis de Sales','Saint','Counter-Reformation saint','Christian','Prayer','A','Bishop of Geneva, Doctor of the Church; author of Introduction to the Devout Life; co-founder of the Visitation order.'),
 ('ENT_EMC_JANE_CHANTAL','Jane Frances de Chantal','Saint','Mendicant/founder','Christian','Prayer','A','French widow and co-founder with Francis de Sales of the Order of the Visitation of Holy Mary.'),
 ('ENT_EMC_CAMILLUS_LELLIS','Camillus de Lellis','Saint','Mendicant/founder','Christian','Healing','A','Italian founder of the Camillians (Ministers of the Sick); patron of the sick, nurses and hospitals.'),
 ('ENT_EMC_JOHN_OF_GOD','John of God','Saint','Mendicant/founder','Christian','Healing','A','Portuguese founder of the Brothers Hospitallers; patron of hospitals, the sick and nurses.'),
 ('ENT_EMC_CATHERINE_RICCI','Catherine dei Ricci','Saint','Mystic/saint','Christian','Prayer','A','Italian Dominican mystic of Prato known for ecstasies of the Passion; correspondent of reformers.'),
 ('ENT_EMC_PETER_CLAVER','Peter Claver','Saint','Counter-Reformation saint','Christian','Mission','A','Spanish Jesuit "slave of the slaves" who ministered to the enslaved at Cartagena; patron of African missions and human rights.'),
 ('ENT_EMC_ALPHONSUS_LIGUORI','Alphonsus Liguori','Saint','Mendicant/founder','Christian','Knowledge','A','Italian founder of the Redemptorists, Doctor of the Church and moral theologian; patron of confessors and moralists.'),
 ('ENT_EMC_PAUL_OF_CROSS','Paul of the Cross','Saint','Mendicant/founder','Christian','Prayer','A','Italian founder of the Passionists, devoted to the Passion of Christ; baroque-era mystic and preacher.'),
 ('ENT_EMC_BENEDICT_LABRE','Benedict Joseph Labre','Saint','Mystic/saint','Christian','Poverty','A','French mendicant pilgrim and "beggar of Rome" (d. 1783); patron of the homeless and of pilgrims.'),
 ('ENT_EMC_ISAAC_JOGUES','Isaac Jogues','Saint','Counter-Reformation saint','Christian','Martyrdom','A','French Jesuit missionary martyred by the Mohawk in 1646; chief among the North American Martyrs.'),
 ('ENT_EMC_JEAN_DE_BREBEUF','Jean de Brébeuf','Saint','Counter-Reformation saint','Christian','Martyrdom','A','French Jesuit missionary to the Huron, martyred 1649; among the North American Martyrs; patron of Canada.'),
 ('ENT_EMC_PETER_FABER','Peter Faber','Saint','Counter-Reformation saint','Christian','Mission','A','Savoyard priest, one of the first companions and co-founders of the Society of Jesus; noted director of the Spiritual Exercises.'),
 ('ENT_EMC_FRANCIS_BORGIA','Francis Borgia','Saint','Counter-Reformation saint','Christian','Mission','A','Spanish duke turned Jesuit; third Superior General of the Society of Jesus and major early Jesuit organizer.'),
 ('ENT_EMC_STANISLAUS_KOSTKA','Stanislaus Kostka','Saint','Counter-Reformation saint','Christian','Prayer','A','Polish Jesuit novice (d. 1568); patron of novices and of Catholic youth.'),
 ('ENT_EMC_MARY_MAGDALENE_PAZZI','Mary Magdalene de'' Pazzi','Saint','Mystic/saint','Christian','Prayer','A','Florentine Carmelite mystic of the Counter-Reformation, known for ecstasies and visions.'),
 ('ENT_EMC_JOSEPH_CUPERTINO','Joseph of Cupertino','Saint','Mystic/saint','Christian','Prayer','A','Italian Conventual Franciscan mystic famed for reported levitations; patron of students and air travelers.'),
 ('ENT_EMC_JOSAPHAT_KUNCEVYC','Josaphat Kuntsevych','Saint','Counter-Reformation saint','Christian','Martyrdom','A','Ruthenian Greek-Catholic archbishop of Polotsk, martyred 1623 for the Union of Brest; first Eastern-rite saint formally canonized.'),
 ('ENT_EMC_OUR_LADY_GUADALUPE','Our Lady of Guadalupe','Marian apparition','Marian apparition','Christian','Protection','A','Marian apparition to Juan Diego at Tepeyac, Mexico (1531); the tilma image; patroness of the Americas and a Marian title of the Virgin Mary.');
